/*
  BANLINHKIEN.COM
  PRJ: XE ROBOT CÂN BẰNG 
  ✅ Phiên bản sửa cho MPU6050 clone
  - Bỏ kiểm tra WHO_AM_I cố định (chấp nhận mọi giá trị phản hồi)
  - Thêm bước “wake up” trước khi đọc dữ liệu
  - Tự động nhận MPU6050 tại địa chỉ 0x68 hoặc 0x69
*/

#include <Wire.h>

byte error, MPU_6050_found = 0, nunchuck_found = 0;
byte lowByte, highByte;
int address, nDevices;

void setup() {
  Wire.begin();
  TWBR = 12; // tốc độ I2C ~400kHz
  Serial.begin(9600);
  Serial.println(F("Scanning I2C bus..."));
}

void loop() {
  Serial.println(F("Scanning I2C bus..."));
  nDevices = 0;

  for (address = 1; address < 127; address++) {
    Wire.beginTransmission(address);
    error = Wire.endTransmission();

    if (error == 0) {
      Serial.print(F("I2C device found at address 0x"));
      if (address < 16) Serial.print("0");
      Serial.println(address, HEX);
      nDevices++;

      // === MPU6050 check ===
      if (address == 0x68 || address == 0x69) {
        Serial.println(F("This could be a MPU-6050 (or compatible clone)"));

        // Wake up the MPU (đánh thức chip)
        Wire.beginTransmission(address);
        Wire.write(0x6B);
        Wire.write(0x00); // clear sleep bit
        Wire.endTransmission();
        delay(10);

        // Đọc thanh ghi WHO_AM_I để tham khảo
        Wire.beginTransmission(address);
        Wire.write(0x75);
        Wire.endTransmission();
        Wire.requestFrom(address, 1);
        while (Wire.available() < 1);
        lowByte = Wire.read();

        Serial.print(F("WHO_AM_I response: 0x"));
        Serial.println(lowByte, HEX);

        // Chấp nhận mọi phản hồi (0x68, 0x72, 0x70...)
        MPU_6050_found = 1;
        Serial.println(F("MPU6050 (clone or real) accepted. Starting Gyro..."));
        set_gyro_registers(address);
      }

      // === Nunchuck check ===
      if (address == 0x52) {
        Serial.println(F("This could be a Nunchuck"));
        Serial.println(F("Trying to initialise the device..."));
        Wire.beginTransmission(0x52);
        Wire.write(0xF0); Wire.write(0x55);
        Wire.endTransmission();
        delay(20);
        Wire.beginTransmission(0x52);

